import{z as r,x as s,o as A,c as d,q as t,j as i,D as o,d as e,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"学校选择与竞争","description":"","frontmatter":{"title":"学校选择与竞争","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-school-choice.md","filePath":"econ/ed2-school-choice.md","lastUpdated":1791063341000}'),c={name:"econ/ed2-school-choice.md"};function h(p,E,u,D,m,f){const B=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="学校选择与竞争" tabindex="-1">学校选择与竞争 <a class="header-anchor" href="#学校选择与竞争" aria-label="Permalink to &quot;学校选择与竞争&quot;">​</a></h1><div class="epigraph"><p>择校的赌注不在家长会不会挑学校，而在学校面对失去学生时会不会变好——前者是分拣，后者才是竞争。</p><footer>—— 据 Tiebout, Journal of Political Economy 1956；Hsieh and Urquiola, Journal of Development Economics 2006 整理</footer></div><p><a href="/econ/ed2-teacher-incentives">上一课</a>把课堂质量的治理对准教师个体；本课把镜头拉到学校之间——家长能不能用脚投票，学校会不会因为丢学生而变好。先划清与既有课的分界：<a href="/econ/school-choice">学校选择</a>讲座位怎么分（机制设计：DA、TTC 与策略性填报），本课讲竞争怎么生产（市场结构：代金券、特许学校与辖区分拣）；分配机制在那里已经讲完，本课只把它当作择校的运输层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞争假说是一条简单的链：家长选校，好学校扩张、差学校退出，平均质量上行。链上有两个可能断开的环节。生产侧：学校是非营利组织，退出威胁弱，管理者未必有提高生产率的动机——竞争的纪律要先穿过治理才到课堂。分拣侧：择校先重排学生，再谈改变教学；同伴构成的变化会伪装成质量变化，被记在竞争的账上。<span class="marginnote">直觉类比：择校像重新洗牌——把好学生换到同一张牌桌上。牌桌上的平均分上去了，但这可能只是「谁跟谁同桌」的变化（分拣）；要证明「竞争让学校变好」（生产），得先证明换了桌的人牌技本身也变好了。</span>用脚投票的原型是 Tiebout 1956：居民按公共品偏好分层入住辖区，教育的居住分拣是它最重的应用——学区房价就是这笔分拣的资本化。本课的问题是：把分拣剥干净之后，竞争本身还剩多少生产率效应。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三类证据，识别强度依次排列。其一，学区内随机抽签：波士顿特许学校按超额报名抽签录取，<a href="/econ/pe-decision-target">以决策为目标</a>口径下的读数是 Abdulkadiroğlu 等 2011 的 QJE 结果——「No Excuses」特许校把中学生的成绩每年抬高约 0.2 个标准差，数学效应更大。其二，全国性代金券：智利 1981 年发全民券，私立学校凭券获得公共经费——供给反应大，但识别混着分拣。其三，辖区竞争：Hoxby 2000 用地貌切割（辖区边界越碎、居民越容易用搬家投票）作为竞争强度的工具变量，得到正效应；Rothstein 2007 指出该工具违反排除约束——边界形态与人口构成相关，估计随之坍塌。<span class="marginnote">术语翻译：工具变量是找一个「只通过竞争强度影响成绩」的外生变量（这里用辖区边界的破碎程度）；排除约束要求它不抄别的近路。Rothstein 的发现是：边界碎的地方人口构成也不同——地貌同时改变同伴构成，近路不止一条，工具随之失效。</span></p><p>三类证据各读到什么、各自的威胁在哪，是识别强度阶梯上的三个台阶。</p>',8)),(A(),i(n,null,{default:o(()=>[l(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22%E5%AD%A6%E5%8C%BA%E9%9A%8F%E6%9C%BA%E6%8A%BD%E7%AD%BE%3A%20%E6%B3%A2%E5%A3%AB%E9%A1%BF%E7%89%B9%E8%AE%B8%22%5D%20--%3E%20I1%5B%22%E5%B9%B2%E5%87%80%E8%AF%BB%E5%88%B0%E7%94%9F%E4%BA%A7%E4%BE%A7%E6%95%88%E5%BA%94%22%5D%0A%20%20E1%20--%3E%20T1%5B%22%E5%A8%81%E8%83%81%3A%20%E5%8F%AA%E5%AF%B9%E7%94%B3%E8%AF%B7%E5%AE%B6%E5%BA%AD%2C%20%E5%A4%96%E6%8E%A8%E5%8F%97%E9%99%90%22%5D%0A%20%20E2%5B%22%E5%85%A8%E5%9B%BD%E4%BB%A3%E9%87%91%E5%88%B8%3A%20%E6%99%BA%E5%88%A9%E5%85%A8%E6%B0%91%E5%88%B8%22%5D%20--%3E%20I2%5B%22%E8%AF%BB%E5%88%B0%E4%BE%9B%E7%BB%99%E4%B8%8E%E9%80%89%E6%8B%A9%E5%8F%8D%E5%BA%94%22%5D%0A%20%20E2%20--%3E%20T2%5B%22%E5%A8%81%E8%83%81%3A%20%E6%B7%B7%E5%85%A5%E5%88%86%E6%8B%A3%2C%20%E8%B0%81%E7%94%A8%E4%BA%86%E5%88%B8%22%5D%0A%20%20E3%5B%22%E8%BE%96%E5%8C%BA%E7%AB%9E%E4%BA%89%3A%20%E5%9C%B0%E8%B2%8C%E5%B7%A5%E5%85%B7%E5%8F%98%E9%87%8F%22%5D%20--%3E%20I3%5B%22%E6%83%B3%E8%AF%BB%E7%AB%9E%E4%BA%89%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20E3%20--%3E%20T3%5B%22%E5%A8%81%E8%83%81%3A%20%E6%8E%92%E9%99%A4%E7%BA%A6%E6%9D%9F%E5%A4%B1%E6%95%88%2C%20%E4%BC%B0%E8%AE%A1%E5%9D%8D%E5%A1%8C%22%5D%0A"})]),fallback:o(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"智利全民券的自然实验给出最冷静的一课：私立入学份额翻了近一倍，全国平均成绩却没有上行，分层反而加剧——择校动员了选择，未必动员了生产（Hsieh–Urquiola 2006）。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("把三条证据放回两环节的框架，读法就清楚了。智利的零效应主要断在分拣：私立扩张吸走的是本来就占优的学生，留下的公立学校同伴变差，平均上互相抵消——竞争的账本被同伴效应记账法吞掉。波士顿的大效应则主要来自生产侧的投入组合：超长学时、高强度辅导、高期望文化，这些都是上一课意义上「买得到的投入」里最贵的质量——特许校赢在把教师激励与投入组合重新配置，不在「竞争」这个抽象名词本身。"),a("span",{class:"marginnote"},"数字实例：每年 0.2 个标准差大约等于把学生从分数分布的第 50 百分位挪到第 58 百分位；连读四年，中游学生与受益学生的差距就能拉开出一整个档位——小数点后的效应，放在四年的复利里并不小。"),e("Hoxby–Rothstein 之争是工具变量的纪律课：地貌不是弱工具，而是失效工具；竞争强度内生地长在人口构成上。合并的结论是：竞争有效应，但效应有条件——供给端要真的能进入和退出，指标要挂在长期产出上，否则择校只是把不平等换了一种排版。")],-1)),(A(),i(n,null,{default:o(()=>[l(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%B6%E9%95%BF%E9%80%89%E6%8B%A9%22%5D%20--%3E%20SO%5B%22%E5%88%86%E6%8B%A3%E9%80%9A%E9%81%93%EF%BC%9A%E5%90%8C%E4%BC%B4%E6%9E%84%E6%88%90%E9%87%8D%E6%8E%92%22%5D%0A%20%20C%20--%3E%20PR%5B%22%E7%94%9F%E4%BA%A7%E9%80%9A%E9%81%93%EF%BC%9A%E8%BF%9B%E5%85%A5%E2%80%93%E9%80%80%E5%87%BA%E5%A8%81%E8%83%81%22%5D%0A%20%20SO%20--%3E%20AVG%5B%22%E5%B9%B3%E5%9D%87%E6%88%90%E7%BB%A9%22%5D%0A%20%20PR%20--%3E%20AVG%0A%20%20SO%20--%3E%20STR%5B%22%E5%88%86%E5%B1%82%E5%8A%A0%E5%89%A7%22%5D%0A%20%20PR%20--%3E%20MIX%5B%22%E6%8A%95%E5%85%A5%E7%BB%84%E5%90%88%E9%87%8D%E6%9E%84%EF%BC%9A%E5%AD%A6%E6%97%B6%E3%80%81%E8%BE%85%E5%AF%BC%E3%80%81%E6%96%87%E5%8C%96%22%5D%0A%20%20MIX%20--%3E%20AVG%0A"})]),fallback:o(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>抽签证据的口径是局部：只对会申请特许校的家庭有效，外推到全体学生要过<a href="/econ/pe-external-validity">外部有效性</a>的断点。供给有约束：好学校扩张受教师市场与场地限制，试点效应搬进全城会稀释。信息也不平等：低收入家庭排序所依赖的信息更少，选择权利的名义平等兑换不成实际平等。最后，分层有独立的规范代价——效率上得分的设计，公平上未必站得住，这是决策课口径下必须分开计价的两栏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞争假说有两个环节：生产侧的进入退出纪律、分拣侧的同伴重排，效应要分开记账。</li><li>波士顿特许抽签：每年约 0.2 个标准差，赢在投入组合，不在抽象的竞争。</li><li>智利全民券：入学结构大变、平均成绩不动——分拣可以吞掉竞争。</li><li>Hoxby 的地貌工具被 Rothstein 推翻：竞争强度内生，工具要过排除约束。</li><li>出处：Tiebout, JPE 1956；Hoxby, AER 2000 与 Rothstein, AER 2007；Hsieh and Urquiola, JDE 2006；Abdulkadiroğlu 等, QJE 2011。</li></ul>',4))])}const b=r(c,[["render",h]]);export{T as __pageData,b as default};
